    activeAnchor,
    anchorElements,
    anchorSelector,
    clickable,
    closeEvents,
    delayHide,
    delayShow,
    disableTooltip,
    float,
    globalCloseEvents,
    handleHideTooltipDelayed,
    handleShow,
    handleShowTooltipDelayed,
    handleTooltipPosition,
    hoveringTooltip,
